function updateBot(bot, className) {
    // Clear previous position
    const prevIndex = bot.y * gridSize + bot.x;
    grid.children[prevIndex].classList.remove(className);

    // Update position
    bot.x = Math.max(0, Math.min(gridSize - 1, bot.x + bot.dx));
    bot.y = Math.max(0, Math.min(gridSize - 1, bot.y + bot.dy));

    // Draw new position
