```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"context"
	"time"
	"github.com/gorilla/mux"
	"github.com/chromedp/chromedp"
)

// FreshdeskWebhookPayload represents the incoming payload from Freshdesk
type FreshdeskWebhookPayload struct {
	ConversationID string `json:"conversation_id"`
	UserID         string `json:"user_id"`
	Message        string `json:"message"`
}

// ConversationState tracks where the user is in the chatbot flow
type ConversationState struct {
	State            string
	ExtractedOrderID string
}

// In-memory store for simplicity (Use Redis/DB in production)
var conversationStates = make(map[string]ConversationState)

const (
	StateGreeting      = "GREETING"
	StateProbing       = "PROBING"
	StateAskOrderNum   = "ASK_ORDER_NUMBER"
	StateAutomating    = "AUTOMATING"
	StateComplete      = "COMPLETE"
)

func main() {
	r := mux.NewRouter()
	// Webhook endpoint for Freshdesk
	r.HandleFunc("/api/webhook/freshdesk", handleFreshdeskWebhook).Methods("POST")
	r.HandleFunc("/api/health", healthCheck).Methods("GET")

	fmt.Println("Server started on port 8080")
	log.Fatal(http.ListenAndServe(":8080", r))
}

func handleFreshdeskWebhook(w http.ResponseWriter, r *http.Request) {
	// 1. SECURITY: Verify Freshdesk signature here (omitted for brevity)

	var payload FreshdeskWebhookPayload
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, "Invalid payload", http.StatusBadRequest)
		return
	}

	// 2. State Machine Logic
	state, exists := conversationStates[payload.ConversationID]
	if !exists {
		state = ConversationState{State: StateGreeting}
		conversationStates[payload.ConversationID] = state
	}

	switch state.State {
	case StateGreeting, StateProbing:
		// Ask probing questions
		sendFreshdeskReply(payload.ConversationID, "Hello! I am the virtual assistant. Can you please describe the issue you are experiencing with your order?")
		state.State = StateAskOrderNum // Move to asking for order number next
		conversationStates[payload.ConversationID] = state

	case StateAskOrderNum:
		// Look for an order number in the message (Assuming 9 digits based on your URL)
		re := regexp.MustCompile(`\b\d{9}\b`)
		match := re.FindString(payload.Message)

		if match != "" {
			state.ExtractedOrderID = match
			state.State = StateAutomating
			conversationStates[payload.ConversationID] = state

			sendFreshdeskReply(payload.ConversationID, fmt.Sprintf("Thank you. I have found your order number %s. I am now looking into this on our internal system. Please hold.", match))

			// Trigger the headless browser automation asynchronously
			go runAzureAutomation(payload.ConversationID, match)
		} else {
			sendFreshdeskReply(payload.ConversationID, "I couldn't find an order number in your message. Could you please provide your 9-digit order number?")
		}
	}

	w.WriteHeader(http.StatusOK)
}

// runAzureAutomation uses chromedp to drive a headless browser
func runAzureAutomation(conversationID, orderID string) {
	// Create context for chromedp
	allocCtx, cancel := chromedp.NewExecAllocator(context.Background(),
		append(chromedp.DefaultExecAllocatorOptions,
			chromedp.Flag("headless", true),
			chromedp.Flag("disable-gpu", true),
			chromedp.Flag("no-sandbox", true), // Required for some server environments
		)...,
	)
	defer cancel()

	ctx, cancel := chromedp.NewContext(allocCtx)
	defer cancel()

	ctx, cancel = context.WithTimeout(ctx, 60*time.Second) // 60 sec timeout
	defer cancel()

	targetURL := fmt.Sprintf("https://applikationen.adlibrisase.p.azurewebsites.net/order/%s", orderID)
	var result string
	var err error

	// SECURITY: Ensure the URL is strictly the expected domain to prevent SSRF
	// In a real app, you'd have more robust validation here.

	err = chromedp.Run(ctx,
		chromedp.Navigate(targetURL),
		// Wait for the search box to be visible. You will need to inspect the Azure site 
		// to get the correct CSS selector for the search box.
		chromedp.WaitVisible(`#search-box-input`, chromedp.ByID),
		// Paste/Clear and type the order number
		chromedp.SendKeys(`#search-box-input`, orderID, chromedp.ByID),
		// Click the search button
		chromedp.Click(`#search-button`, chromedp.ByID),
		// Wait for results
		chromedp.WaitVisible(`.order-result`, chromedp.ByQuerySelector),
		// Extract some text to send back to the customer
		chromedp.Text(`.order-status-text`, &result, chromedp.ByQuerySelector),
	)

	if err != nil {
		log.Printf("Automation failed for conversation %s: %v", conversationID, err)
		sendFreshdeskReply(conversationID, "I apologize, but I encountered an error while checking your order. Transferring you to a human agent.")
		return
	}

	// Send the extracted result back to Freshdesk
	sendFreshdeskReply(conversationID, fmt.Sprintf("I have checked your order. Current status: %s. Is there anything else I can help with?", result))

	// Update state
	state := conversationStates[conversationID]
	state.State = StateComplete
	conversationStates[conversationID] = state
}

// sendFreshdeskReply mocks sending a message back to Freshdesk API
func sendFreshdeskReply(conversationID, message string) {
	// In production, use net/http to POST to Freshdesk's API
	// e.g., POST https://domain.freshdesk.com/api/v2/conversations/{id}/messages
	log.Printf("Sending to Freshdesk Conv %s: %s", conversationID, message)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "healthy"})
}
