<?php
if (!defined('ABSPATH')) exit;

class WPSW_Wallet {

    public static function get_balance($user_id = null) {
        if (!$user_id) {
            $user_id = get_current_user_id();
        }
        if (!$user_id) return 0.0;

        $balance = get_user_meta($user_id, '_wpsw_balance', true);
        return $balance ? floatval($balance) : 0.0;
    }

    public static function update_balance($user_id, $amount, $type = 'credit', $description = '', $reference = '') {
        global $wpdb;

        if (!$user_id) return false;

        $amount = floatval($amount);
        if ($amount <= 0) return false;

        $current_balance = self::get_balance($user_id);

        if ($type === 'credit') {
            $new_balance = $current_balance + $amount;
        } elseif ($type === 'debit') {
            if ($current_balance < $amount) return false;
            $new_balance = $current_balance - $amount;
        } else {
            return false;
        }

        $table = WPSW_Database::get_table_name();

        $result = $wpdb->insert(
            $table,
            array(
                'user_id'       => $user_id,
                'type'          => $type,
                'amount'        => $amount,
                'balance_after' => $new_balance,
                'description'   => $description,
                'reference'     => $reference,
                'status'        => 'completed',
                'created_at'    => current_time('mysql'),
            ),
            array('%d', '%s', '%f', '%f', '%s', '%s', '%s', '%s')
        );

        if ($result === false) return false;

        update_user_meta($user_id, '_wpsw_balance', $new_balance);

        do_action('wpsw_balance_updated', $user_id, $type, $amount, $new_balance);

        return $new_balance;
    }

    public static function get_transactions($user_id = null, $limit = 20, $offset = 0) {
        global $wpdb;

        if (!$user_id) {
            $user_id = get_current_user_id();
        }
        if (!$user_id) return array();

        $table = WPSW_Database::get_table_name();
        $sql = $wpdb->prepare(
            "SELECT * FROM $table WHERE user_id = %d ORDER BY created_at DESC, id DESC LIMIT %d OFFSET %d",
            $user_id, $limit, $offset
        );

        return $wpdb->get_results($sql);
    }

    public static function get_transaction_count($user_id = null) {
        global $wpdb;
        if (!$user_id) $user_id = get_current_user_id();
        if (!$user_id) return 0;

        $table = WPSW_Database::get_table_name();
        return (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $table WHERE user_id = %d", $user_id));
    }

    public static function format_amount($amount) {
        return number_format(floatval($amount), 2, '.', ',');
    }
}
