### 2.2. Model Manager (`model.js`)
This file handles the creation, training, and inference logic using TensorFlow.js.

```javascript
const tf = require('@tensorflow/tfjs-node');

class DemandPredictionModel {
  constructor() {
    this.model = null;
    this.isTrained = false;
  }

  async init() {
    this.model = tf.sequential();

    // Simple Feed-Forward Neural Network
    this.model.add(tf.layers.dense({ inputShape: [4], units: 16, activation: 'relu' }));
    this.model.add(tf.layers.dense({ units: 8, activation: 'relu' }));
    this.model.add(tf.layers.dense({ units: 1, activation: 'linear' }));

    this.model.compile({
      optimizer: tf.train.adam(0.05),
      loss: 'meanSquaredError'
    });
  }

  async train(trainingData) {
    const { inputs, labels } = this.preprocessData(trainingData);

    const xs = tf.tensor2d(inputs);
    const ys = tf.tensor2d(labels);

    await this.model.fit(xs, ys, {
      epochs: 50,
      batchSize: 32,
      shuffle: true,
      callbacks: {
        onEpochEnd: (epoch, logs) => {
          if (epoch % 10 === 0) console.log(`Epoch ${epoch}: loss = ${logs.loss}`);
        }
      }
    });

    this.isTrained = true;
    xs.dispose();
    ys.dispose();
  }

  predict(input) {
    if (!this.isTrained) throw new Error('Model is not trained yet.');
    const inputTensor = tf.tensor2d([input]);
    const prediction = this.model.predict(inputTensor);
    const result = prediction.dataSync()[0];

    inputTensor.dispose();
    prediction.dispose();

    return { expectedReservations: parseFloat(result.toFixed(2)) };
  }

  preprocessData(data) {
    // In a real scenario, this would fetch from a DB or parse a large dataset
    // Mocking some training data for demonstration
    const inputs = data.map(d => [d.dayOfWeek, d.month, d.isHoliday, d.historicalAvg]);
    const labels = data.map(d => [d.actualReservations]);
    return { inputs, labels };
  }
}

module.exports = new DemandPredictionModel();
```

### 2.3. Server and REST API (`server.js`)
This file sets up the Express server and defines the endpoints.

```javascript
const express = require('express');
const cors = require('cors');
const demandModel = require('./model');

const app = express();
app.use(cors());
app.use(express.json());

// Initialize and train the model on startup with mock data
async function initializeModel() {
  await demandModel.init();
  const mockTrainingData = [
    { dayOfWeek: 1, month: 6, isHoliday: 0, historicalAvg: 40, actualReservations: 42 },
    { dayOfWeek: 5, month: 6, isHoliday: 1, historicalAvg: 80, actualReservations: 95 },
    // ... add more mock data for training
  ];
  await demandModel.train(mockTrainingData);
  console.log('Model initialized and trained successfully.');
}

initializeModel().catch(console.error);

// --- REST API Endpoints ---

/**
 * GET /health
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'OK', modelTrained: demandModel.isTrained });
});

/**
 * POST /api/v1/predict
 * Predict reservation demand based on input features
 */
app.post('/api/v1/predict', (req, res) => {
  try {
    const { dayOfWeek, month, isHoliday, historicalAvg } = req.body;

    if ([dayOfWeek, month, isHoliday, historicalAvg].some(v => v === undefined)) {
      return res.status(400).json({ success: false, error: 'Missing required fields' });
    }

    const input = [dayOfWeek, month, isHoliday, historicalAvg];
    const prediction = demandModel.predict(input);

    res.status(200).json({
      success: true,
      prediction
    });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

/**
 * POST /api/v1/train
 * Endpoint to retrain the model with new data (Admin only in production)
 */
app.post('/api/v1/train', async (req, res) => {
  try {
    const { trainingData } = req.body;
    if (!trainingData || !Array.isArray(trainingData)) {
      return res.status(400).json({ success: false, error: 'Invalid training data format.' });
    }

    await demandModel.train(trainingData);
    res.status(200).json({ success: true, message: 'Model retrained successfully.' });
  } catch (error) {
    res.status(500).json({ success: false, error: error.message });
  }
});

const PORT = process.env.PORT || 3004;
app.listen(PORT, () => {
  console.log(`TensorFlow.js Microservice running on port ${PORT}`);
});

module.exports = app; // Export for testing
```

