// Recursive helper function for DFS traversal
void dfs_helper(const vector<vector<int>>& graph, int node, vector<bool>& visited) {
    // Mark the current node as visited and print it
    visited[node] = true;
    cout << node << " ";

    // Recur for all the adjacent vertices
    for (int adj : graph[node]) {
        if (!visited[adj]) {
            dfs_helper(graph, adj, visited);
        }
    }
}

// DFS traversal of the graph
void dfs_recursive(const vector<vector<int>>& graph, int start) {
    vector<bool> visited(graph.size(), false);
    dfs_helper(graph, start, visited);
