### 2. Iterative DFS Implementation
If you want to avoid recursion limits (e.g., stack overflow errors on very deep graphs), you can use an explicit stack to perform DFS iteratively.

```cpp
#include <iostream>
#include <vector>
#include <stack>
using namespace std;

// Iterative DFS traversal of the graph
void dfs_iterative(const vector<vector<int>>& graph, int start) {
    vector<bool> visited(graph.size(), false);
    stack<int> st;

    // Push the starting node onto the stack
    st.push(start);

    while (!st.empty()) {
        int node = st.top();
        st.pop();

        // If the node hasn't been visited, mark it and print it
        if (!visited[node]) {
            visited[node] = true;
            cout << node << " ";
        }

        // Push all unvisited adjacent vertices onto the stack
        // Note: We push them in reverse order if we want to match the exact 
        // left-to-right traversal order of the recursive approach.
        for (int i = graph[node].size() - 1; i >= 0; i--) {
            int adj = graph[node][i];
            if (!visited[adj]) {
                st.push(adj);
            }
        }
    }
}

int main() {
    int V = 5;
    vector<vector<int>> graph(V);

    // Add edges
    graph[0].push_back(1);
    graph[0].push_back(2);
    graph[1].push_back(2);
    graph[2].push_back(0);
    graph[2].push_back(3);
    graph[3].push_back(3);

    cout << "Iterative DFS traversal starting from node 2:\n";
    dfs_iterative(graph, 2);
    cout << "\n";

    return 0;
}
